import itertools
from math import gcd

# Witness is embedded; no file, network, stream, or process access anywhere.
R = 3
RANGE_N = [1, 2, 3, 4, 5, 6, 7]
CLAIMED = [1, 2, 2, 3, 3, 3, 3]

def max_good(N, r):
    pts = list(range(1, N + 1))
    for k in range(len(pts), -1, -1):
        for S in itertools.combinations(pts, k):
            ok = True
            for T in itertools.combinations(S, r):
                g = [gcd(T[i], T[j]) for i in range(r) for j in range(i + 1, r)]
                if len(set(g)) == 1:
                    ok = False
                    break
            if ok:
                return k
    return 0

def verify() -> bool:
    assert R == 3
    assert RANGE_N == [1, 2, 3, 4, 5, 6, 7]
    assert len(CLAIMED) == 7
    for N in RANGE_N:
        if max_good(N, R) != CLAIMED[N - 1]:
            return False
    for i in range(1, 7):  # monotonicity sanity
        if CLAIMED[i] < CLAIMED[i - 1]:
            return False
    return True

RESULT = verify()
assert RESULT, "FAIL: witness does not verify"
# exit 0 iff every claim verified exactly; any failure raises (fail closed)
